#!/usr/bin/env bash
set -uo pipefail
POINTER="$HOME/.cache/larch/sessions/current-implement-env-4242.sh"
[ -f "$POINTER" ] && [ ! -L "$POINTER" ] || { printf '%s\n' "implement-run: missing current-env pointer: $POINTER" >&2; exit 2; }
IMPLEMENT_TMPDIR=$(awk 'BEGIN{p="IMPLEMENT_TMPDIR="} index($0,p)==1{print substr($0,length(p)+1); found=1; exit} END{exit found ? 0 : 1}' "$POINTER" 2>/dev/null) || { printf '%s\n' "implement-run: IMPLEMENT_TMPDIR missing from pointer: $POINTER" >&2; exit 2; }
[ -n "$IMPLEMENT_TMPDIR" ] || { printf '%s\n' "implement-run: IMPLEMENT_TMPDIR empty in pointer: $POINTER" >&2; exit 2; }
case "$IMPLEMENT_TMPDIR" in /*) ;; *) printf '%s\n' "implement-run: IMPLEMENT_TMPDIR must be absolute: $IMPLEMENT_TMPDIR" >&2; exit 2 ;; esac
LARCH_RUN_SH="$IMPLEMENT_TMPDIR/larch-run.sh"
[ -f "$LARCH_RUN_SH" ] || { printf '%s\n' "implement-run: missing larch-run.sh: $LARCH_RUN_SH" >&2; exit 2; }
[ -x "$LARCH_RUN_SH" ] || { printf '%s\n' "implement-run: larch-run.sh is not executable: $LARCH_RUN_SH" >&2; exit 2; }
export IMPLEMENT_TMPDIR
export LARCH_CLAUDE_PID="${LARCH_CLAUDE_PID:-4242}"
exec "$LARCH_RUN_SH" "$@"
